file.content:
  font-family: var(--font-mono);
  font-size: 12px;
  line-height: 1.6;
  color: var(--text);
  overflow-x: auto;
  white-space: pre;
  margin-bottom: 8px;
}

.prompt-pattern {
  border-left: 3px solid var(--accent);
  border-radius: 0 4px 4px 0;
  white-space: pre-wrap;
  word-break: break-word;
}

/* ===== Improvements List ===== */
.improvements-list {
  list-style: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 20px;
  counter-reset: improvements;
}

.improvements-list li {
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: 12px;
  counter-increment: improvements;
}

.improvements-list li::before {
  content: counter(improvements);
  font-size: 18px;
  font-weight: 700;
  font-family: var(--font-mono);
  color: var(--text-muted);
  line-height: 1.4;
}

.improvement-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 6px;
}

.improvement-detail {
  font-size: 14px;
  line-height: 1.6;
  color: var(--text-secondary);
}

/* ===== Session Artifacts ===== */
.session-artifacts-list {
  list-style: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.session-artifacts-list li {
  font-size: 13px;
  display: flex;
  gap: 8px;
  align-items: baseline;
}

.session-artifacts-list .artifact-name {
  font-weight: 500;
  flex-shrink: 0;
}

.session-artifacts-list .artifact-path {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--accent);
  flex-shrink: 0;
  display: inline;
}

.session-artifacts-list .artifact-desc {
  color: var(--text-secondary);
}

/* ===== Verdict Statement ===== */
.verdict-statement-card {
  border-color: var(--border);
}

.verdict-statement {
  font-size: 14px;
  font-style: italic;
  line-height: 1.7;
  color: var(--text-secondary);
}

/* ===== Transcript ===== */
.collapsible-trigger {
  cursor: pointer;
  list-style: none;
  user-select: none;
}

.collapsible-trigger::before {
  content: '▸ ';
  display: inline;
}

details[open] .collapsible-trigger::before { content: '▾ '; }

.transcript-container { margin-top: 16px; }

.turn {
  padding: 10px 14px;
  border-left: 3px solid var(--border);
  margin-bottom: 8px;
}

.turn.human { border-left-color: var(--accent); }
.turn.assistant { border-left-color: var(--green); }

.turn-header {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: var(--text-secondary);
  margin-bottom: 6px;
}

.turn-role { font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; }
.turn-content { font-size: 13px; white-space: pre-wrap; word-break: break-word; }

.turn-content pre {
  background: var(--bg-code);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 10px;
  overflow-x: auto;
  font-family: var(--font-mono);
  font-size: 12px;
  margin: 6px 0;
}

/* ===== Screenshots ===== */
.screenshot-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 12px;
}

.screenshot-item {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  cursor: pointer;
}

.screenshot-item img {
  width: 100%;
  display: block;
}

.screenshot-label {
  padding: 7px 12px;
  font-size: 12px;
  color: var(--text-secondary);
  background: var(--bg);
}

/* ===== Screenshot Modal ===== */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.88);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  cursor: pointer;
}

.modal-overlay img {
  max-width: 90vw;
  max-height: 90vh;
  border-radius: var(--radius);
}

/* ===== Rounds Nav ===== */
.rounds-nav {
  display: flex;
  gap: 8px;
}

.round-btn {
  padding: 6px 16px;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--text);
  cursor: pointer;
  font-size: 13px;
}

.round-btn.active { border-color: var(--accent); background: rgba(0, 112, 243, 0.1); }

/* ===== Footer ===== */
.footer {
  text-align: center;
  padding: 24px;
  font-size: 12px;
  color: var(--text-secondary);
  border-top: 1px solid var(--border);
  margin-top: 24px;
  display: flex;
  justify-content: center;
  gap: 16px;
}

/* ===== Responsive ===== */
@media (max-width: 900px) {
  .proof-layout { grid-template-columns: 1fr; }
  .proof-sidebar { position: static; }
  .three-col { grid-template-columns: 1fr; }
  .header-stats { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 640px) {
  .container { padding: 12px 12px 32px; }
  .stats-row { grid-template-columns: repeat(2, 1fr); }
  .verdict-banner { flex-wrap: wrap; }
  .verdict-detail { margin-left: 0; width: 100%; }
  .two-col-grid { grid-template-columns: 1fr; }
  .header-stats { grid-template-columns: repeat(2, 1fr); }
  .tab-nav-wrapper { margin: 0 -12px; padding: 0 12px; }
}
